{
  "name": "opencode-branch-memory-manager",
  "version": "0.1.9",
  "description": "Automatically manages branch-specific context for OpenCode with auto-save, auto-load, and git workflow integration",
  "author": "Davidcreador",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Davidcreador/opencode-branch-memory-manager.git"
  },
  "homepage": "https://github.com/Davidcreador/opencode-branch-memory-manager#readme",
  "bugs": {
    "url": "https://github.com/Davidcreador/opencode-branch-memory-manager/issues"
  },
  "files": [
    ".opencode",
    "dist"
  ],
  "scripts": {
    "build": "npm run build:local && npm run build:npm",
    "build:npm": "cd src && bun install --no-lockfile && bun build index.ts --outdir ../dist --target node",
    "build:plugin": "bun build .opencode/plugin/branch-memory-plugin.ts --outdir .opencode/dist --target node --format esm",
    "build:tools": "bun build .opencode/tool/branch-memory.ts --outdir .opencode/dist --target node --format esm",
    "build:local": "npm run build:plugin && npm run build:tools",
    "typecheck": "tsc --noEmit --project tsconfig.typecheck.json --skipLibCheck",
    "test": "bun test",
    "test:coverage": "bun test --coverage",
    "lint": "eslint src tests --ext .ts",
    "lint:fix": "eslint src tests --ext .ts --fix",
    "clean": "rm -rf dist node_modules src/node_modules .opencode/dist",
    "prepublishOnly": "npm run clean && npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "branch-memory",
    "context",
    "git",
    "auto-save",
    "workspace"
  ],
  "opencode": {
    "type": "plugin"
  },
  "dependencies": {
    "chokidar": "^4.0.0",
    "zod": "^3.22.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "engines": {
    "node": ">=18.0.0",
    "bun": ">=1.0.0"
  },
  "directories": {
    "test": "tests"
  }
}
